import{z as i,x as B,o as A,c as C,q as n,j as l,D as E,d as t,s,S as o,b as e}from"./chunks/framework.C8m1ZpeB.js";const S=JSON.parse('{"title":"ACME","description":"","frontmatter":{"title":"ACME","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/acme.md","filePath":"cs/acme.md","lastUpdated":1791413859000}'),p={name:"cs/acme.md"};function d(T,a,c,m,D,h){const r=B("Mermaid");return A(),C("div",null,[a[2]||(a[2]=n('<h1 id="acme" tabindex="-1">ACME <a class="header-anchor" href="#acme" aria-label="Permalink to &quot;ACME&quot;">​</a></h1><div class="epigraph"><p>Let’s Encrypt 把「证明你控制该域名」收成 HTTP-01 / DNS-01 挑战，证书申请从工单变成协议。自动化降低过期，也把挑战实现错误变成新的攻击面。</p><footer>—— RFC 8555；Barnes et al., Automatic Certificate Management Environment</footer></div><p>上一课<a href="/cs/certificate-transparency">CT</a>要求证书可被看见。缺口是<strong>谁有资格让 CA 签这张叶</strong>：ACME 用挑战证明控制权，替换人工邮件确认。不重写链验证。</p><p>后课默认已经读完本课钉下的合同，只补差，不从该领域第一性原理重开。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>手工签发导致过期与弱私钥。ACME：账户密钥、订单、挑战、下载。HTTP-01 在约定路径放令牌；DNS-01 放 TXT。缺口是挑战的绑定：若攻击者能写你的 <code>.well-known</code> 或改你的 DNS，就能申请到证——这是控制面安全，不是 AES 的锅。</p><h3 id="通配与多名字" tabindex="-1">通配与多名字 <a class="header-anchor" href="#通配与多名字" aria-label="Permalink to &quot;通配与多名字&quot;">​</a></h3><p>一张证多个 SAN 要每个都过挑战。通配通常强制 DNS-01。</p><p><span class="marginnote">RFC 8555。Let’s Encrypt 是部署实例，协议不绑一家 CA。本课不提供抢注或劫持挑战的步骤。</span></p><p><span class="marginnote">术语翻译：DNS-01 挑战就是「CA 让你在该域名的 DNS 里放一条指定内容的 TXT 记录，它再去查询核对」。能改一个域名的 DNS，通常就意味着真的控制它——所以泛域名证书（形如星号点 example.com）一般强制走 DNS-01。</span></p><p><span class="marginnote">数字实例：Let&#39;s Encrypt 签发的证书有效期是 90 天。看似很短，但 ACME 把续期做成了全自动（定时任务跑一遍挑战即可），短有效期才可行——私钥泄露后的可用窗口也按同样比例缩短。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>按账户→订单→挑战→签发走状态机。强调私钥在申请人主机生成，CA 只签公钥。续期同样要过挑战。对照：企业私有 CA 可用同一思想走内部 ACME。</p>',13)),(A(),l(o,null,{default:E(()=>[s(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20ACC%5B%22%E8%B4%A6%E6%88%B7%E9%92%A5%22%5D%20--%3E%20ORD%5B%22%E8%AE%A2%E5%8D%95%20FQDN%22%5D%0A%20%20ORD%20--%3E%20CH%5B%22HTTP-01%20%E6%88%96%20DNS-01%22%5D%0A%20%20CH%20--%3E%20CRT%5B%22CA%20%E7%AD%BE%E5%8F%B6%E8%AF%81%E4%B9%A6%22%5D%0A%20%20CRT%20--%3E%20CT2%5B%22%E4%BB%8D%E5%BA%94%E8%BF%9B%20CT%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[t(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("h2",{id:"机制",tabindex:"-1"},[t("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[4]||(a[4]=e("p",null,"身份证明从「组织开信」改成「当时能写该名下的资源」。TLS 的保密不自动保护挑战路径：HTTP-01 常先走 80 端口。CAA 记录限制哪些 CA 可签，是另一层政策。",-1)),a[5]||(a[5]=e("p",null,"第一张图画的是 ACME 的四个环节怎么连；这张图回答第二个问题：一次 HTTP-01 挑战里双方各做什么、CA 到底验证的是什么绑定。",-1)),(A(),l(o,null,{default:E(()=>[s(r,{id:"mermaid-47",class:"mermaid",graph:"flowchart%20TD%0A%20%20REQ%5B%22%E5%AE%A2%E6%88%B7%E7%AB%AF%E4%B8%BA%E5%9F%9F%E5%90%8D%E4%B8%8B%E5%8D%95%22%5D%20--%3E%20GEN%5B%22%E6%9C%AC%E5%9C%B0%E7%94%9F%E6%88%90%E5%AF%86%E9%92%A5%E5%AF%B9%EF%BC%8C%E5%8F%AA%E4%B8%8A%E4%BA%A4%E5%85%AC%E9%92%A5%22%5D%0A%20%20GEN%20--%3E%20TOK%5B%22CA%20%E4%B8%8B%E5%8F%91%E4%B8%80%E6%AC%A1%E6%80%A7%E4%BB%A4%E7%89%8C%22%5D%0A%20%20TOK%20--%3E%20PLACE%5B%22%E6%8A%8A%E4%BB%A4%E7%89%8C%E6%94%BE%E5%88%B0%E7%BA%A6%E5%AE%9A%E8%B7%AF%E5%BE%84%E4%B8%8B%22%5D%0A%20%20PLACE%20--%3E%20FETCH%5B%22CA%20%E4%B8%BB%E5%8A%A8%E6%9D%A5%E6%8B%89%E5%8F%96%E8%AF%A5%E8%B7%AF%E5%BE%84%22%5D%0A%20%20FETCH%20--%3E%20MATCH%7B%22%E4%BB%A4%E7%89%8C%E5%AF%B9%E5%BE%97%E4%B8%8A%EF%BC%9F%22%7D%0A%20%20MATCH%20--%3E%7C%22%E6%98%AF%22%7C%20SIGN%5B%22%E7%AD%BE%E5%8F%91%E5%8F%B6%E8%AF%81%E4%B9%A6%22%5D%0A%20%20MATCH%20--%3E%7C%22%E5%90%A6%22%7C%20FAIL%5B%22%E8%AE%A2%E5%8D%95%E5%A4%B1%E8%B4%A5%22%5D%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[t(" Loading... ",-1)])]),_:1})),a[6]||(a[6]=n('<p><span class="marginnote">常见误区：初学者容易以为「能上 HTTPS 了，网站就安全了」。ACME 只证明「申请那一刻有人控制该域名」：若攻击者能写你的点 well-known 目录或改你的 DNS 记录，它同样能通过挑战、以你的名义拿到正规证书。这是控制面的洞，与 TLS 加密强度无关。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不写全部挑战类型的边界案例。下一课 TLS 攻击史：套件与实现的历史失败，默认假设证书验证与 ACME 已在。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>CT 看见证书；ACME 证明当时控制该名。</li><li>挑战实现错误等于把签发权交给能写 Web/DNS 的人。</li><li>私钥本地生成；续期仍要挑战。</li><li>下一课：TLS 攻击史当合同对照。</li><li>出处：RFC 8555；Let’s Encrypt 设计叙述；对照 RFC 5280。</li></ul>',5))])}const u=i(p,[["render",d]]);export{S as __pageData,u as default};
